const htmlContent = $input.item.json.content;
const slug = $('Create Title, Slug, Meta').item.json.slug || $('Create Title, Slug, Meta').item.json.output?.slug || 'article';
const fileName = `${slug}.html`;

return {
  json: $input.item.json,
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(htmlContent, 'utf-8'),
      fileName,
      'text/html'
    )
  }
};
